-- Two real (tiny) mp4s, stored as Postgres large objects. lo_from_bytea creates the
-- large object from the decoded bytes and returns its oid; byte_size is derived so it
-- always matches. These are small enough to embed here; in a real app you would stream
-- the upload into a large object instead of base64-ing it into SQL.

with clip as (
  select decode('', 'base64') as bytes
)
insert into videos (title, content_type, loid, byte_size)
select 'Solid colour (48x48, 1s)', 'video/mp4', lo_from_bytea(0, bytes), length(bytes) from clip;

with clip as (
  select decode('', 'base64') as bytes
)
insert into videos (title, content_type, loid, byte_size)
select 'Test pattern (64x64, 2s)', 'video/mp4', lo_from_bytea(0, bytes), length(bytes) from clip;
